content.result:
  1 | /* ── Reset & tokens ─────────────────────────────────────────────────────── */
  2 | *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  3 | 
  4 | :root {
  5 |   --bg:     #0d1117;
  6 |   --bg2:    #161b22;
  7 |   --bg3:    #21262d;
  8 |   --border: #30363d;
  9 |   --text:   #e6edf3;
 10 |   --muted:  #8b949e;
 11 |   --accent: #58a6ff;
 12 |   --green:  #3fb950;
 13 |   --red:    #f85149;
 14 |   --gold:   #d29922;
 15 |   --purple: #a371f7;
 16 |   --orange: #f0883e;
 17 |   --radius: 8px;
 18 |   --shadow: 0 4px 24px rgba(0,0,0,.5);
 19 |   /* shared column widths — used by both table-head and .row */
 20 |   --c-rank:   32px;
 21 |   --c-spark:  80px;
 22 |   --c-ticker: 100px;
 23 |   --c-price:  80px;
 24 |   --c-chg:    68px;
 25 |   --c-score:  58px;
 26 |   --c-pe:     52px;
 27 |   --c-rsi:    46px;
 28 |   --c-eps:    64px;
 29 |   --c-margin: 64px;
 30 |   --c-cap:    72px;
 31 | }
 32 | 
 33 | /* ── Light mode token overrides ─────────────────────────────────────────── */
 34 | body.light {
 35 |   --bg:     #ffffff;
 36 |   --bg2:    #f6f8fa;
 37 |   --bg3:    #eaeef2;
 38 |   --border: #d0d7de;
 39 |   --text:   #1f2328;
 40 |   --muted:  #656d76;
 41 |   --accent: #0969da;
 42 |   --green:  #1a7f37;
 43 |   --red:    #cf222e;
 44 |   --gold:   #9a6700;
 45 |   --shadow: 0 4px 24px rgba(0,0,0,.12);
 46 | }
 47 | 
 48 | body {
 49 |   background: var(--bg);
 50 |   color: var(--text);
 51 |   font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
 52 |   font-size: 13px;
 53 |   line-height: 1.4;
 54 |   min-height: 100vh;
 55 |   transition: background .2s, color .2s;
 56 | }
 57 | 
 58 | /* ── Toolbar (header + controls in one bar) ── */
 59 | header {
 60 |   background: var(--bg2);
 61 |   border-bottom: 1px solid var(--border);
 62 |   position: sticky;
 63 |   top: 0;
 64 |   z-index: 100;
 65 | }
 66 | .toolbar {
 67 |   max-width: 1400px;
 68 |   margin: 0 auto;
 69 |   padding: 0 20px;
 70 |   height: 48px;
 71 |   display: flex;
 72 |   align-items: center;
 73 |   gap: 20px;
 74 | }
 75 | .logo { display: flex; align-items: center; gap: 8px; font-size: 1rem; font-weight: 700; white-space: nowrap; }
 76 | .logo-ai { color: var(--accent); }
 77 | .toolbar-controls { display: flex; align-items: center; gap: 14px; flex: 1; }
 78 | .toolbar-right { display: flex; align-items: center; gap: 12px; margin-left: auto; white-space: nowrap; }
 79 | 
 80 | /* Controls */
 81 | .control-group { display: flex; align-items: center; gap: 5px; }
 82 | .control-group label { font-size: .72rem; color: var(--muted); text-transform: uppercase; letter-spacing: .05em; white-space: nowrap; }
 83 | .control-group select {
 84 |   background: var(--bg3);
 85 |   border: 1px solid var(--border);
 86 |   color: var(--text);
 87 |   border-radius: 6px;
 88 |   padding: 3px 8px;
 89 |   font-size: .8rem;
 90 |   cursor: pointer;
 91 |   height: 26px;
 92 | }
 93 | 
 94 | /* Buttons */
 95 | .btn { border: none; border-radius: 6px; padding: 4px 12px; font-size: .8rem; font-weight: 600; cursor: pointer; transition: opacity .15s, transform .1s; height: 26px; }
 96 | .btn:hover { opacity: .85; }
 97 | .btn:active { transform: scale(.97); }
 98 | .btn-primary    { background: var(--accent); color: #fff; }
 99 | .btn-theme      { background: var(--bg3); color: var(--text); border: 1px solid var(--border); padding: 4px 9px; font-size: .9rem; }
100 | .btn-secondary  { background: var(--bg3); color: var(--accent); border: 1px solid var(--accent); }
101 | .btn-portfolio  { background: var(--bg3); color: var(--gold); border: 1px solid var(--gold); }
102 | 
103 | /* Custom ticker input */
104 | .custom-ticker-group { gap: 4px; }
105 | .custom-ticker-input { background: var(--bg3); border: 1px solid var(--border); color: var(--text); border-radius: 6px; padding: 3px 8px; font-size: .8rem; height: 26px; width: 80px; text-transform: uppercase; }
106 | .custom-ticker-input:focus { outline: none; border-color: var(--accent); }
107 | 
108 | .timestamp { color: var(--muted); font-size: .75rem; }
109 | 
110 | /* ── Alert banner ── */
111 | .alert-banner { max-width: 1400px; margin: 0 auto; padding: 8px 20px; font-size: .82rem; font-weight: 600; background: rgba(210,153,34,.15); border-bottom: 1px solid var(--gold); color: var(--gold); display: flex; align-items: center; flex-wrap: wrap; gap: 6px; }
112 | .alert-banner.hidden { display: none; }
113 | .alert-item { font-weight: 400; }
114 | 
115 | /* ── Status banner ── */
116 | .status-banner { max-width: 1400px; margin: 8px auto 0; padding: 7px 20px; border-radius: var(--radius); font-size: .85rem; font-weight: 600; }
117 | .status-banner.error   { background: rgba(248,81,73,.15); border: 1px solid var(--red); color: var(--red); }
118 | .status-banner.success { background: rgba(63,185,80,.12); border: 1px solid var(--green); color: var(--green); }
119 | .status-banner.info    { background: rgba(88,166,255,.10); border: 1px solid var(--accent); color: var(--accent); }
120 | .status-banner.hidden  { display: none; }
121 | 
122 | /* ── Container ── */
123 | .container { max-width: 1400px; margin: 0 auto; padding: 10px 20px 32px; }
124 | 
125 | /* ── Loading ── */
126 | .loading-screen { display: flex; flex-direction: column; align-items: center; gap: 16px; padding: 60px 0; color: var(--muted); }
127 | .spinner { width: 36px; height: 36px; border: 3px solid var(--border); border-top-color: var(--accent); border-radius: 50%; animation: spin .8s linear infinite; }
128 | @keyframes spin { to { transform: rotate(360deg); } }
129 | 
130 | /* ── Table header row ── */
131 | .table-head {
132 |   display: grid;
133 |   grid-template-columns:
134 |     var(--c-rank) var(--c-spark) var(--c-ticker) var(--c-price)
135 |     var(--c-chg) var(--c-score) var(--c-pe) var(--c-rsi)
136 |     var(--c-eps) var(--c-margin) var(--c-cap);
137 |   align-items: center;
138 |   padding: 0 10px;
139 |   height: 28px;
140 |   border-bottom: 1px solid var(--border);
141 |   margin-bottom: 2px;
142 |   font-size: .68rem;
143 |   color: var(--muted);
144 |   text-transform: uppercase;
145 |   letter-spacing: .05em;
146 | }
147 | .col-rank   { text-align: center; }
148 | .col-price, .col-chg, .col-score, .col-pe, .col-rsi, .col-eps, .col-margin, .col-cap { text-align: right; }
149 | 
150 | /* ── Cards list (one row per stock) ── */
151 | .cards-grid { display: flex; flex-direction: column; gap: 3px; }
152 | .hidden { display: none !important; }
153 | 
154 | /* ── Stock row (compact table-style card) ── */
155 | .card {
156 |   display: grid;
157 |   grid-template-columns:
158 |     var(--c-rank) var(--c-spark) var(--c-ticker) var(--c-price)
159 |     var(--c-chg) var(--c-score) var(--c-pe) var(--c-rsi)
160 |     var(--c-eps) var(--c-margin) var(--c-cap);
161 |   align-items: center;
162 |   padding: 0 10px;
163 |   height: 44px;
164 |   background: var(--bg2);
165 |   border: 1px solid var(--border);
166 |   border-radius: var(--radius);
167 |   cursor: pointer;
168 |   transition: background .12s, border-color .12s;
169 | }
170 | .card:hover { background: var(--bg3); border-color: var(--accent); }
171 | 
172 | /* rank */
173 | .row-rank { text-align: center; font-size: .75rem; color: var(--muted); font-weight: 600; }
174 | .row-rank.top3 { color: var(--gold); font-weight: 700; }
175 | 
176 | /* sparkline cell */
177 | .row-spark { width: var(--c-spark); height: 36px; display: flex; align-items: center; padding: 0 4px; }
178 | .row-spark canvas { display: block; width: 100%; height: 36px; }
179 | 
180 | /* ticker + name stacked */
181 | .row-ticker { display: flex; flex-direction: column; gap: 1px; overflow: hidden; padding-right: 6px; }
182 | .row-ticker-sym { font-size: .85rem; font-weight: 700; white-space: nowrap; }
183 | .row-ticker-name { font-size: .68rem; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
184 | 
185 | /* right-aligned cells */
186 | .row-price  { text-align: right; font-size: .82rem; font-weight: 600; padding-right: 6px; }
187 | .row-chg    { text-align: right; padding-right: 6px; }
188 | .row-score  { text-align: right; font-size: .85rem; font-weight: 800; padding-right: 6px; }
189 | .row-pe, .row-rsi, .row-eps, .row-margin, .row-cap { text-align: right; font-size: .78rem; color: var(--muted); padding-right: 6px; }
190 | 
191 | /* change text (no pill background — just color) */
192 | .chg { font-size: .78rem; font-weight: 600; }
193 | .chg.pos { color: var(--green); }
194 | .chg.neg { color: var(--red); }
195 | .chg.neu { color: var(--muted); }
196 | 
197 | /* score colour */
198 | .score-val.high   { color: var(--green); }
199 | .score-val.medium { color: var(--gold); }
200 | .score-val.low    { color: var(--red); }
201 | 
202 | /* Subscore weight tag in modal */
203 | .subscore-weight {
204 |   margin-left: 5px;
205 |   font-size: .68rem;
206 |   color: var(--accent);
207 |   opacity: .8;
208 | }
209 | 
210 | /* Yahoo Finance links */
211 | .yf-link { color: var(--accent); text-decoration: none; }
212 | .yf-link:hover { text-decoration: underline; }
213 | .modal-yf-link { font-size: .75rem; margin-top: 3px; display: inline-block; }
214 | 
215 | /* ── Weight bar ── */
216 | .weight-bar {
217 |   background: var(--bg2);
218 |   border-bottom: 1px solid var(--border);
219 |   padding: 5px 20px;
220 |   display: flex;
221 |   align-items: center;
222 |   gap: 8px;
223 |   flex-wrap: wrap;
224 |   max-width: 100%;
225 |   overflow: hidden;
226 | }
227 | .weight-bar-label {
228 |   font-size: .7rem;
229 |   color: var(--muted);
230 |   text-transform: uppercase;
231 |   letter-spacing: .05em;
232 |   white-space: nowrap;
233 | }
234 | .weight-pill {
235 |   display: inline-flex;
236 |   align-items: center;
237 |   gap: 5px;
238 |   background: var(--bg3);
239 |   border: 1px solid var(--border);
240 |   border-radius: 20px;
241 |   padding: 2px 9px;
242 |   font-size: .72rem;
243 |   white-space: nowrap;
244 | }
245 | .weight-pill-name  { color: var(--muted); }
246 | .weight-pill-val   { color: var(--text); font-weight: 600; }
247 | .weight-pill-track {
248 |   width: 36px;
249 |   height: 4px;
250 |   background: var(--bg);
251 |   border-radius: 2px;
252 |   overflow: hidden;
253 | }
254 | .weight-pill-fill  {
255 |   height: 100%;
256 |   border-radius: 2px;
257 |   background: var(--accent);
258 |   transition: width .4s ease;
259 | }
260 | 
261 | /* ── Score bars (modal) ── */
262 | .subscore-bar-wrap { display: flex; align-items: center; gap: 10px; margin-bottom: 7px; }
263 | .subscore-label { width: 85px; font-size: .78rem; color: var(--muted); flex-shrink: 0; }
264 | .subscore-track { flex: 1; height: 6px; border-radius: 4px; background: var(--bg3); overflow: hidden; }
265 | .subscore-fill  { height: 100%; border-radius: 4px; background: var(--accent); }
266 | .subscore-val   { width: 32px; text-align: right; font-size: .78rem; font-weight: 600; }
267 | 
268 | /* metrics grid (modal) */
269 | .metrics-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 6px; margin-bottom: 12px; }
270 | .metric { background: var(--bg3); border-radius: 6px; padding: 6px 8px; display: flex; flex-direction: column; gap: 2px; }
271 | .metric-label { font-size: .65rem; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; }
272 | .metric-value { font-size: .88rem; font-weight: 700; }
273 | 
274 | /* 52-week range bar (modal) */
275 | .range-bar-wrap { margin-bottom: 10px; }
276 | .range-bar-labels { display: flex; justify-content: space-between; font-size: .68rem; color: var(--muted); margin-bottom: 3px; }
277 | .range-bar-track { height: 5px; border-radius: 3px; background: var(--bg3); position: relative; }
278 | .range-bar-fill { position: absolute; left: 0; top: 0; height: 100%; border-radius: 3px; background: linear-gradient(90deg, var(--accent), var(--green)); }
279 | .range-bar-dot { position: absolute; top: 50%; transform: translate(-50%,-50%); width: 9px; height: 9px; border-radius: 50%; background: var(--text); border: 2px solid var(--bg2); }
280 | 
281 | /* rationale (modal) */
282 | .rationale-item { font-size: .8rem; color: var(--muted); margin-bottom: 5px; }
283 | 
284 | /* ticker circle (modal) */
285 | .ticker-circle { width: 40px; height: 40px; border-radius: 10px; background: var(--bg3); display: flex; align-items: center; justify-content: center; font-size: .78rem; font-weight: 700; color: var(--accent); flex-shrink: 0; }
286 | 
287 | /* score ring (modal) */
288 | .score-ring { border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; font-weight: 800; border: 2px solid; width: 36px; height: 36px; font-size: .88rem; vertical-align: middle; }
289 | .score-ring.high   { border-color: var(--green); color: var(--green); }
290 | .score-ring.medium { border-color: var(--gold);  color: var(--gold); }
291 | .score-ring.low    { border-color: var(--red);   color: var(--red); }
292 | 
293 | /* ── Legend ── */
294 | .legend { border-top: 1px solid var(--border); padding: 12px 0 24px; }
295 | .legend details summary { font-size: .78rem; color: var(--muted); cursor: pointer; user-select: none; padding: 4px 0; }
296 | .legend details summary:hover { color: var(--text); }
297 | .legend-grid { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; margin-bottom: 10px; }
298 | .legend-item { display: flex; align-items: center; gap: 6px; font-size: .78rem; color: var(--muted); }
299 | .pill { font-size: .68rem; font-weight: 700; padding: 1px 6px; border-radius: 20px; }
300 | .pill-blue   { background: rgba(88,166,255,.15);  color: var(--accent); }
301 | .pill-green  { background: rgba(63,185,80,.15);   color: var(--green); }
302 | .pill-purple { background: rgba(163,113,247,.15); color: var(--purple); }
303 | .pill-orange { background: rgba(240,136,62,.15);  color: var(--orange); }
304 | .pill-red    { background: rgba(248,81,73,.15);   color: var(--red); }
305 | .disclaimer  { font-size: .72rem; color: var(--muted); padding: 8px 12px; background: var(--bg2); border-radius: 6px; border: 1px solid var(--border); }
306 | 
307 | /* ── Modal ── */
308 | .modal-overlay { position: fixed; inset: 0; background: rgba(0,0,0,.72); z-index: 200; display: flex; align-items: center; justify-content: center; padding: 20px; }
309 | .modal { background: var(--bg2); border: 1px solid var(--border); border-radius: var(--radius); max-width: 540px; width: 100%; max-height: 88vh; overflow-y: auto; padding: 22px; position: relative; box-shadow: var(--shadow); }
310 | .modal-close { position: absolute; top: 12px; right: 12px; background: var(--bg3); border: 1px solid var(--border); color: var(--text); border-radius: 6px; width: 26px; height: 26px; font-size: .9rem; cursor: pointer; display: flex; align-items: center; justify-content: center; }
311 | .modal h2 { font-size: 1.15rem; margin-bottom: 2px; }
312 | .modal .modal-sub { color: var(--muted); font-size: .8rem; margin-bottom: 14px; }
313 | .modal-section { margin-bottom: 14px; }
314 | .modal-section h4 { font-size: .7rem; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); margin-bottom: 8px; }
315 | 
316 | /* ── Score history chart (modal) ── */
317 | .score-history-canvas { display: block; width: 100%; border-radius: 6px; }
318 | .score-history-empty  { font-size: .78rem; color: var(--muted); padding: 10px 0; }
319 | 
320 | /* ── Alert inputs (modal) ── */
321 | .alert-inputs { display: flex; flex-wrap: wrap; align-items: flex-end; gap: 10px; }
322 | .alert-label  { display: flex; flex-direction: column; gap: 4px; font-size: .75rem; color: var(--muted); }
323 | .alert-input  { background: var(--bg3); border: 1px solid var(--border); color: var(--text); border-radius: 6px; padding: 4px 8px; font-size: .82rem; height: 26px; width: 120px; }
324 | .alert-input:focus { outline: none; border-color: var(--accent); }
325 | 
326 | /* ── Portfolio panel ── */
327 | .portfolio-panel {
328 |   max-width: 1400px;
329 |   margin: 0 auto 0;
330 |   background: var(--bg2);
331 |   border: 1px solid var(--border);
332 |   border-radius: var(--radius);
333 |   padding: 16px 20px 12px;
334 |   margin-top: 8px;
335 | }
336 | .portfolio-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; }
337 | .portfolio-header h3 { font-size: .95rem; font-weight: 700; }
338 | .portfolio-hint { font-size: .75rem; color: var(--muted); margin-bottom: 12px; }
339 | 
340 | /* Summary row */
341 | .portfolio-summary { display: flex; gap: 24px; flex-wrap: wrap; background: var(--bg3); border-radius: 6px; padding: 10px 14px; margin-bottom: 12px; border: 1px solid var(--border); }
342 | .port-stat { display: flex; flex-direction: column; gap: 2px; }
343 | .port-stat-label { font-size: .68rem; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); }
344 | .port-stat-value { font-size: 1rem; font-weight: 700; color: var(--text); }
345 | 
346 | /* ── Portfolio tabs ── */
347 | .port-tabs { display: flex; gap: 4px; background: var(--bg3); border: 1px solid var(--border); border-radius: 7px; padding: 3px; }
348 | .port-tab  { background: transparent; border: none; border-radius: 5px; color: var(--muted); font-size: .78rem; font-weight: 600; padding: 3px 12px; cursor: pointer; transition: background .15s, color .15s; height: 24px; white-space: nowrap; }
349 | .port-tab.active { background: var(--accent); color: #fff; }
350 | .port-tab:not(.active):hover { color: var(--text); background: var(--border); }
351 | 
352 | /* ── Recommendations tab ── */
353 | .rec-header-row { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; gap: 12px; flex-wrap: wrap; }
354 | .rec-loading     { display: flex; align-items: center; gap: 8px; color: var(--muted); font-size: .82rem; padding: 10px 0; }
355 | 
356 | /* Health bar */
357 | .rec-health { display: flex; align-items: center; gap: 16px; background: var(--bg3); border: 1px solid var(--border); border-radius: 8px; padding: 12px 16px; margin-bottom: 14px; flex-wrap: wrap; }
358 | .rec-health-ring { width: 52px; height: 52px; border-radius: 50%; border: 3px solid; display: flex; align-items: center; justify-content: center; font-size: 1.1rem; font-weight: 800; flex-shrink: 0; }
359 | .rec-health-ring.strong { border-color: var(--green); color: var(--green); }
360 | .rec-health-ring.good   { border-color: var(--accent); color: var(--accent); }
361 | .rec-health-ring.fair   { border-color: var(--gold);   color: var(--gold); }
362 | .rec-health-ring.weak   { border-color: var(--red);    color: var(--red); }
363 | .rec-health-info { flex: 1; min-width: 0; }
364 | .rec-health-label  { font-weight: 700; font-size: .88rem; margin-bottom: 2px; }
365 | .rec-health-summary { font-size: .75rem; color: var(--muted); line-height: 1.5; }
366 | .rec-health-meta   { display: flex; gap: 18px; margin-top: 8px; flex-wrap: wrap; }
367 | .rec-health-stat   { font-size: .72rem; color: var(--muted); }
368 | .rec-health-stat strong { color: var(--text); }
369 | 
370 | /* Concentration bar */
371 | .rec-sector-bar  { margin-bottom: 14px; }
372 | .rec-sector-bar h5 { font-size: .7rem; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); margin-bottom: 6px; }
373 | .rec-conc-row    { display: flex; align-items: center; gap: 8px; margin-bottom: 4px; font-size: .75rem; }
374 | .rec-conc-label  { width: 120px; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex-shrink: 0; }
375 | .rec-conc-track  { flex: 1; height: 6px; background: var(--bg3); border-radius: 3px; overflow: hidden; }
376 | .rec-conc-fill   { height: 100%; border-radius: 3px; transition: width .4s; }
377 | .rec-conc-fill.over  { background: var(--red); }
378 | .rec-conc-fill.warn  { background: var(--gold); }
379 | .rec-conc-fill.ok    { background: var(--accent); }
380 | .rec-conc-pct    { width: 38px; text-align: right; color: var(--muted); }
381 | 
382 | /* Action cards */
383 | .rec-section-title { font-size: .7rem; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); margin: 14px 0 6px; }
384 | .rec-cards         { display: flex; flex-direction: column; gap: 6px; }
385 | .rec-card {
386 |   display: flex; align-items: flex-start; gap: 10px;
387 |   background: var(--bg3); border: 1px solid var(--border);
388 |   border-radius: 8px; padding: 10px 12px;
389 |   border-left-width: 3px;
390 | }
391 | .rec-card.trim      { border-left-color: var(--red); }
392 | .rec-card.add       { border-left-color: var(--green); }
393 | .rec-card.hold      { border-left-color: var(--muted); }
394 | .rec-card.rebalance { border-left-color: var(--gold); }
