185 | // ── Sparkline (pure canvas, compact 36 px tall) ───────────────────────────
186 | function drawSparkline(s) {
187 |   const canvas = document.getElementById(`spark-${s.ticker}`);
188 |   if (!canvas || !s.sparkline || s.sparkline.length < 2) return;
189 | 
190 |   const dpr = window.devicePixelRatio || 1;
191 |   const w   = canvas.parentElement.clientWidth - 8; // subtract padding
192 |   const h   = 36;
193 |   canvas.width  = w * dpr;
194 |   canvas.height = h * dpr;
195 |   canvas.style.width  = w + 'px';
196 |   canvas.style.height = h + 'px';
197 |   const ctx = canvas.getContext('2d');
198 |   ctx.scale(dpr, dpr);
199 | 
200 |   const prices = s.sparkline;
201 |   const min    = Math.min(...prices);
202 |   const max    = Math.max(...prices);
203 |   const range  = max - min || 1;
204 |   const pad    = 2;
205 |   const xFn    = i => (i / (prices.length - 1)) * (w - pad * 2) + pad;
206 |   const yFn    = v => h - pad - ((v - min) / range) * (h - pad * 2);
207 | 
208 |   const isUp = prices[prices.length - 1] >= prices[0];
209 |   const col  = isUp ? '63,185,80' : '248,81,73';
210 |   const grad = ctx.createLinearGradient(0, 0, 0, h);
211 |   grad.addColorStop(0, `rgba(${col},.25)`);
212 |   grad.addColorStop(1, `rgba(${col},0)`);
213 | 
214 |   // filled area
215 |   ctx.beginPath();
216 |   ctx.moveTo(xFn(0), yFn(prices[0]));
217 |   prices.forEach((p, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(p)); });
218 |   ctx.lineTo(xFn(prices.length - 1), h);
219 |   ctx.lineTo(xFn(0), h);
220 |   ctx.closePath();
221 |   ctx.fillStyle = grad;
222 |   ctx.fill();
223 | 
224 |   // line
225 |   ctx.beginPath();
226 |   ctx.moveTo(xFn(0), yFn(prices[0]));
227 |   prices.forEach((p, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(p)); });
228 |   ctx.strokeStyle = `rgb(${col})`;
229 |   ctx.lineWidth   = 1.5;
230 |   ctx.lineJoin    = 'round';
231 |   ctx.stroke();
232 | }
