353 | // FEATURE 5 — Historical AI Score chart
354 | // ══════════════════════════════════════════════════════════════════════════════
355 | 
356 | /** Save the current score for each ticker with a UTC timestamp. */
357 | function persistScoreHistory(stocks) {
358 |   let history = {};
359 |   try { history = JSON.parse(localStorage.getItem(LS_SCORES) || '{}'); } catch {}
360 |   const ts = Date.now();
361 |   stocks.forEach(s => {
362 |     if (!history[s.ticker]) history[s.ticker] = [];
363 |     // Only append if the last entry was > 5 minutes ago (avoid duplicates on rapid refresh)
364 |     const last = history[s.ticker].at(-1);
365 |     if (!last || ts - last.ts > 5 * 60 * 1000) {
366 |       history[s.ticker].push({ ts, score: s.score });
367 |     }
368 |     // Keep only the last 60 data points per ticker
369 |     if (history[s.ticker].length > 60) history[s.ticker] = history[s.ticker].slice(-60);
370 |   });
371 |   try { localStorage.setItem(LS_SCORES, JSON.stringify(history)); } catch {}
372 | }
373 | 
374 | /** Draw a compact line chart of score-over-time onto #score-history-canvas. */
375 | function drawScoreHistoryChart(ticker) {
376 |   let history = {};
377 |   try { history = JSON.parse(localStorage.getItem(LS_SCORES) || '{}'); } catch {}
378 |   const points = history[ticker] || [];
379 | 
380 |   const canvas  = document.getElementById('score-history-canvas');
381 |   const emptyEl = document.getElementById('score-history-empty');
382 |   if (!canvas) return;
383 | 
384 |   if (points.length < 2) {
385 |     canvas.style.display = 'none';
386 |     emptyEl && emptyEl.classList.remove('hidden');
387 |     return;
388 |   }
389 |   emptyEl && emptyEl.classList.add('hidden');
390 |   canvas.style.display = 'block';
391 | 
392 |   const dpr = window.devicePixelRatio || 1;
393 |   const W   = canvas.parentElement.clientWidth || 400;
394 |   const H   = 80;
395 |   canvas.width  = W * dpr;
396 |   canvas.height = H * dpr;
397 |   canvas.style.width  = W + 'px';
398 |   canvas.style.height = H + 'px';
399 | 
400 |   const ctx = canvas.getContext('2d');
401 |   ctx.scale(dpr, dpr);
402 | 
403 |   const scores = points.map(p => p.score);
404 |   const minS   = Math.min(...scores);
405 |   const maxS   = Math.max(...scores);
406 |   const range  = Math.max(maxS - minS, 5);
407 |   const pad    = { t: 6, b: 18, l: 6, r: 6 };
408 |   const iW     = W - pad.l - pad.r;
409 |   const iH     = H - pad.t - pad.b;
410 | 
411 |   const xFn = i => pad.l + (i / (points.length - 1)) * iW;
412 |   const yFn = v => pad.t + iH - ((v - minS) / range) * iH;
413 | 
414 |   ctx.fillStyle = '#21262d';
415 |   ctx.fillRect(0, 0, W, H);
416 | 
417 |   const grad = ctx.createLinearGradient(0, pad.t, 0, pad.t + iH);
418 |   grad.addColorStop(0, 'rgba(88,166,255,0.35)');
419 |   grad.addColorStop(1, 'rgba(88,166,255,0.02)');
420 |   ctx.beginPath();
421 |   ctx.moveTo(xFn(0), yFn(scores[0]));
422 |   scores.forEach((v, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(v)); });
423 |   ctx.lineTo(xFn(scores.length - 1), pad.t + iH);
424 |   ctx.lineTo(xFn(0), pad.t + iH);
425 |   ctx.closePath();
426 |   ctx.fillStyle = grad;
427 |   ctx.fill();
428 | 
429 |   ctx.beginPath();
430 |   ctx.moveTo(xFn(0), yFn(scores[0]));
431 |   scores.forEach((v, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(v)); });
432 |   ctx.strokeStyle = '#58a6ff';
433 |   ctx.lineWidth   = 2;
434 |   ctx.lineJoin    = 'round';
435 |   ctx.stroke();
436 | 
437 |   const special = new Set([0, scores.length - 1,
438 |     scores.indexOf(Math.min(...scores)), scores.indexOf(Math.max(...scores))]);
439 |   ctx.textAlign = 'center';
440 |   special.forEach(i => {
441 |     const x = xFn(i), y = yFn(scores[i]);
442 |     ctx.beginPath();
443 |     ctx.arc(x, y, 2.5, 0, Math.PI * 2);
444 |     ctx.fillStyle = '#58a6ff';
445 |     ctx.fill();
446 |     const labelY = y < pad.t + 12 ? y + 12 : y - 5;
447 |     ctx.fillStyle = '#8b949e';
448 |     ctx.font = '9px sans-serif';
449 |     ctx.fillText(scores[i], x, labelY);
450 |   });
451 | 
452 |   ctx.fillStyle = '#8b949e';
453 |   ctx.font = '9px sans-serif';
454 |   ctx.textAlign = 'left';
455 |   ctx.fillText(fmtDate(points[0].ts), pad.l, H - 4);
456 |   ctx.textAlign = 'right';
457 |   ctx.fillText(fmtDate(points.at(-1).ts), W - pad.r, H - 4);
458 | }
459 | 
460 | function fmtDate(ts) {
461 |   const d = new Date(ts);
462 |   return `${d.getMonth()+1}/${d.getDate()} ${d.getHours()}:${String(d.getMinutes()).padStart(2,'0')}`;
463 | }
