/* ── Cards list (one row per stock) ── */
.cards-grid { display: flex; flex-direction: column; gap: 3px; }
.hidden { display: none !important; }

/* ── Card stagger slide-in animation ── */
@keyframes cardSlideIn {
  from {
    opacity: 0;
    transform: translateX(-18px) scaleY(0.92);
  }
  to {
    opacity: 1;
    transform: translateX(0) scaleY(1);
  }
}
.card-enter {
  animation: cardSlideIn 0.38s cubic-bezier(0.22, 0.61, 0.36, 1) both;
}

/* ── Live feed "pump" animation — new card drops in from top ── */
@keyframes cardDropIn {
  0%   { opacity: 0; transform: translateY(-24px) scale(0.97); }
  60%  { opacity: 1; transform: translateY(3px) scale(1.005); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}
.card-drop {
  animation: cardDropIn 0.45s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}

/* ── Live feed glow pulse on a newly arrived card ── */
@keyframes cardGlow {
  0%   { box-shadow: 0 0 0 0 rgba(88,166,255,0); border-color: var(--accent); }
  40%  { box-shadow: 0 0 18px 4px rgba(88,166,255,0.35); border-color: var(--accent); }
  100% { box-shadow: 0 0 0 0 rgba(88,166,255,0); border-color: var(--border); }
}
.card-glow {
  animation: cardGlow 1.6s ease-out forwards;
}

/* ── LIVE badge + controls ── */
.live-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: .7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--green);
  white-space: nowrap;
}
.live-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green);
  flex-shrink: 0;
}
@keyframes livePulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50%       { opacity: 0.35; transform: scale(0.7); }
}
.live-dot.pulsing {
  animation: livePulse 1.1s ease-in-out infinite;
}

/* ── Feed progress bar under toolbar ── */
.feed-progress-bar {
  height: 2px;
  background: var(--bg3);
  width: 100%;
  overflow: hidden;
  position: relative;
}
.feed-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent), var(--green));
  width: 0%;
  transition: width 0.25s linear;
  border-radius: 1px;
}

/* ── Score counter animation ── */
@keyframes scoreCountUp {
  from { opacity: 0.3; }
  to   { opacity: 1; }
}
.score-counting {
  animation: scoreCountUp 0.5s ease-out;
}

/* ── Rank badge pop for top 3 ── */
@keyframes rankPop {
  0%   { transform: scale(0.5); opacity: 0; }
  70%  { transform: scale(1.25); opacity: 1; }
  100% { transform: scale(1); }
}
.row-rank.top3 {
  animation: rankPop 0.55s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}

/* ── Refresh button spin ── */
@keyframes btnSpin {
  to { transform: rotate(360deg); }
}
.btn-spinning {
  display: inline-block;
  animation: btnSpin 0.7s linear infinite;
}

