169 |   const chgClass   = s.change1d > 0 ? 'pos' : s.change1d < 0 ? 'neg' : 'neu';
170 |   const chgSign    = s.change1d > 0 ? '+' : '';
171 |   const medals     = ['🥇','🥈','🥉'];
172 |   const rankLabel  = rank <= 3 ? medals[rank - 1] : `#${rank}`;
173 | 
174 |   card.innerHTML = `
175 |     <div class="row-rank ${rank<=3?'top3':''}">${rankLabel}</div>
176 |     <div class="row-spark"><canvas id="spark-${s.ticker}"></canvas></div>
177 |     <div class="row-ticker">
178 |       <a class="row-ticker-sym yf-link" href="https://finance.yahoo.com/quote/${s.ticker}" target="_blank" rel="noopener" onclick="event.stopPropagation()">${s.ticker} ↗</a>
179 |       <span class="row-ticker-name">${s.name}</span>
180 |     </div>
181 |     <div class="row-price">$${s.currentPrice.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</div>
182 |     <div class="row-chg"><span class="chg ${chgClass}">${chgSign}${s.change1d.toFixed(2)}%</span></div>
183 |     <div class="row-score"><span class="score-val ${scoreClass}">${s.score}</span></div>
184 |     <div class="row-pe">${s.pe ?? '—'}</div>
185 |     <div class="row-rsi">${s.rsi}</div>
186 |     <div class="row-eps">${s.epsGrowth != null ? s.epsGrowth + '%' : '—'}</div>
187 |     <div class="row-margin">${s.profitMargin != null ? s.profitMargin + '%' : '—'}</div>
