193 | // ── Sparkline (pure canvas, compact 36 px tall) ───────────────────────────
194 | function drawSparkline(s) {
195 |   const canvas = document.getElementById(`spark-${s.ticker}`);
196 |   if (!canvas || !s.sparkline || s.sparkline.length < 2) return;
197 | 
198 |   const dpr = window.devicePixelRatio || 1;
199 |   const w   = canvas.parentElement.clientWidth - 8; // subtract padding
200 |   const h   = 36;
201 |   canvas.width  = w * dpr;
202 |   canvas.height = h * dpr;
203 |   canvas.style.width  = w + 'px';
204 |   canvas.style.height = h + 'px';
205 |   const ctx = canvas.getContext('2d');
206 |   ctx.scale(dpr, dpr);
207 | 
208 |   const prices = s.sparkline;
209 |   const min    = Math.min(...prices);
210 |   const max    = Math.max(...prices);
211 |   const range  = max - min || 1;
212 |   const pad    = 2;
213 |   const xFn    = i => (i / (prices.length - 1)) * (w - pad * 2) + pad;
214 |   const yFn    = v => h - pad - ((v - min) / range) * (h - pad * 2);
215 | 
216 |   const isUp = prices[prices.length - 1] >= prices[0];
217 |   const col  = isUp ? '63,185,80' : '248,81,73';
218 |   const grad = ctx.createLinearGradient(0, 0, 0, h);
219 |   grad.addColorStop(0, `rgba(${col},.25)`);
220 |   grad.addColorStop(1, `rgba(${col},0)`);
221 | 
222 |   // filled area
223 |   ctx.beginPath();
224 |   ctx.moveTo(xFn(0), yFn(prices[0]));
225 |   prices.forEach((p, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(p)); });
226 |   ctx.lineTo(xFn(prices.length - 1), h);
227 |   ctx.lineTo(xFn(0), h);
228 |   ctx.closePath();
229 |   ctx.fillStyle = grad;
230 |   ctx.fill();
231 | 
232 |   // line
233 |   ctx.beginPath();
234 |   ctx.moveTo(xFn(0), yFn(prices[0]));
235 |   prices.forEach((p, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(p)); });

235 |   prices.forEach((p, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(p)); });
236 |   ctx.strokeStyle = `rgb(${col})`;
237 |   ctx.lineWidth   = 1.5;
238 |   ctx.lineJoin    = 'round';
239 |   ctx.stroke();
240 | }
