/* rank */
.row-rank { text-align: center; font-size: .75rem; color: var(--muted); font-weight: 600; transition: transform .2s cubic-bezier(0.34,1.56,0.64,1); }
.row-rank.top3 { color: var(--gold); font-weight: 700; }
.card:hover .row-rank { transform: scale(1.35); }

/* sparkline cell */
.row-spark { width: var(--c-spark); height: 36px; display: flex; align-items: center; padding: 0 4px; transition: filter .2s, transform .2s; }
.row-spark canvas { display: block; width: 100%; height: 36px; transition: filter .2s; }
.card:hover .row-spark { transform: scaleY(1.12); }
.card:hover .row-spark canvas { filter: brightness(1.35) drop-shadow(0 0 4px rgba(88,166,255,0.5)); }

/* ticker + name stacked */
.row-ticker { display: flex; flex-direction: column; gap: 1px; overflow: hidden; padding-right: 6px; }
