.row-ticker-name { font-size: .68rem; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; transition: color .15s; }
.card:hover .row-ticker-sym  { color: var(--accent); letter-spacing: .03em; }
.card:hover .row-ticker-name { color: var(--text); }

/* right-aligned cells */
.row-price  { text-align: right; font-size: .82rem; font-weight: 600; padding-right: 6px; transition: transform .15s; }
.row-chg    { text-align: right; padding-right: 6px; }
.row-score  { text-align: right; font-size: .85rem; font-weight: 800; padding-right: 6px; transition: transform .2s cubic-bezier(0.34,1.56,0.64,1); }
.row-pe, .row-rsi, .row-eps, .row-margin, .row-cap { text-align: right; font-size: .78rem; color: var(--muted); padding-right: 6px; transition: color .15s; }
.card:hover .row-price  { transform: scale(1.06); }
.card:hover .row-score  { transform: scale(1.18); }
.card:hover .row-pe, .card:hover .row-rsi,
.card:hover .row-eps, .card:hover .row-margin,
.card:hover .row-cap    { color: var(--text); }

