/* ── Refresh button spin ── */
@keyframes btnSpin {
  to { transform: rotate(360deg); }
}
.btn-spinning {
  display: inline-block;
  animation: btnSpin 0.7s linear infinite;
}

/* ── 50% click rejection — card shake + red flash ── */
@keyframes cardReject {
  0%   { transform: translateX(0)   scale(1);    background: var(--bg2);              border-color: var(--border); }
  10%  { transform: translateX(-8px) scale(1.01); background: rgba(248,81,73,0.18);   border-color: var(--red); }
  25%  { transform: translateX( 8px) scale(1.01); background: rgba(248,81,73,0.25);   border-color: var(--red); }
  40%  { transform: translateX(-6px) scale(1.01); background: rgba(248,81,73,0.18);   border-color: var(--red); }
  55%  { transform: translateX( 5px) scale(1.0);  background: rgba(248,81,73,0.12);   border-color: var(--red); }
  70%  { transform: translateX(-3px) scale(1.0);  background: rgba(248,81,73,0.07);   border-color: var(--red); }
  85%  { transform: translateX( 2px) scale(1.0);  background: rgba(248,81,73,0.03);   border-color: var(--border); }
  100% { transform: translateX(0)   scale(1);    background: var(--bg2);              border-color: var(--border); }
}
.card-rejected {
  animation: cardReject 0.55s cubic-bezier(0.36, 0.07, 0.19, 0.97) both !important;
  pointer-events: none;
}

/* ── Rejection toast notification ── */
.rejection-toast {
  position: fixed;
  bottom: 28px;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: rgba(248, 81, 73, 0.92);
  color: #fff;
  font-size: .82rem;
  font-weight: 600;
  padding: 10px 20px;
  border-radius: 24px;
  white-space: nowrap;
  pointer-events: none;
