/* ══════════════════════════════════════════════════════════════════════════
   DENIAL OVERLAY — full-screen DENIED animation
   ══════════════════════════════════════════════════════════════════════════ */

/* Red vignette border flash around the whole screen */
@keyframes vignetteFlash {
  0%   { opacity: 0; }
  15%  { opacity: 1; }
  55%  { opacity: 0.7; }
  100% { opacity: 0; }
}
.denial-vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 8000;
  box-shadow: inset 0 0 120px 40px rgba(248, 81, 73, 0.55);
  animation: vignetteFlash 1.1s ease-out forwards;
}

/* Dark overlay behind the stamp */
@keyframes overlayFade {
  0%   { opacity: 0; }
  20%  { opacity: 1; }
  65%  { opacity: 0.85; }
  100% { opacity: 0; }
}
.denial-overlay {
  position: fixed;
  inset: 0;
  background: rgba(20, 0, 0, 0.72);
  pointer-events: none;
  z-index: 8001;
  animation: overlayFade 1.1s ease-out forwards;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* The DENIED stamp itself */
@keyframes stampSlam {
  0%   { transform: scale(4) rotate(-12deg); opacity: 0; }
  18%  { transform: scale(0.88) rotate(3deg); opacity: 1; }
  30%  { transform: scale(1.08) rotate(-1.5deg); opacity: 1; }
  42%  { transform: scale(0.96) rotate(0.8deg); opacity: 1; }
  55%  { transform: scale(1.0)  rotate(0deg);   opacity: 1; }
  75%  { transform: scale(1.0)  rotate(0deg);   opacity: 1; }
  100% { transform: scale(1.0)  rotate(0deg);   opacity: 0; }
}
.denial-stamp {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  border: 6px solid var(--red);
  border-radius: 10px;
  padding: 18px 44px;
  color: var(--red);
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  box-shadow:
    0 0 0 3px rgba(248,81,73,0.3),
    0 0 60px 10px rgba(248,81,73,0.25);
  background: rgba(248,81,73,0.07);
  animation: stampSlam 1.1s cubic-bezier(0.22, 0.61, 0.36, 1) forwards;
  user-select: none;
}
.denial-stamp-icon {
  font-size: 3.2rem;
  line-height: 1;
  filter: drop-shadow(0 0 12px rgba(248,81,73,0.7));
}
.denial-stamp-text {
  font-size: 3rem;
  line-height: 1;
  text-shadow: 0 0 24px rgba(248,81,73,0.7);
}
.denial-stamp-sub {
  font-size: 0.85rem;
  letter-spacing: 0.1em;
  color: rgba(248,81,73,0.75);
  font-weight: 600;
  text-align: center;
  max-width: 320px;
}

/* Snarky message bar slides up from bottom */
@keyframes denialMsgSlide {
  0%   { transform: translateY(100%); opacity: 0; }
  18%  { transform: translateY(-6px); opacity: 1; }
  28%  { transform: translateY(0);    opacity: 1; }
  72%  { transform: translateY(0);    opacity: 1; }
  100% { transform: translateY(100%); opacity: 0; }
}
.denial-msg-bar {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--red);
  color: #fff;
  text-align: center;
  font-size: 0.92rem;
  font-weight: 700;
  padding: 14px 24px;
  z-index: 8002;
  pointer-events: none;
  animation: denialMsgSlide 1.1s cubic-bezier(0.22, 0.61, 0.36, 1) forwards;
  letter-spacing: 0.02em;
  box-shadow: 0 -4px 24px rgba(248,81,73,0.5);
}

