function rejectClick(card, ticker) {
  // Don't pile on rejections if already shaking
  if (card.classList.contains('card-rejected')) return;

  // Flash the card red + shake
  card.classList.add('card-rejected');
  card.addEventListener('animationend', () => {
    card.classList.remove('card-rejected');
  }, { once: true });

  // Pick a random snarky message and show a toast
  const msg = REJECTION_MSGS[Math.floor(Math.random() * REJECTION_MSGS.length)];
  showRejectionToast(`${ticker} — ${msg}`);
}

let _toastTimer = null;
function showRejectionToast(msg) {
  let toast = document.getElementById('rejection-toast');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'rejection-toast';
    toast.className = 'rejection-toast';
    document.body.appendChild(toast);
  }

  // Reset animation by removing + re-adding class
  toast.classList.remove('rejection-toast-show');
  void toast.offsetWidth; // force reflow
  toast.textContent = msg;
  toast.classList.add('rejection-toast-show');

  clearTimeout(_toastTimer);
  _toastTimer = setTimeout(() => {
    toast.classList.remove('rejection-toast-show');
  }, 2800);
}

